        "title": "એક પાસાને ફેંકવાના પ્રયોગનો વિચાર કરીએ. એક અવિભાજ્ય પૂર્ણાંક મળે તેને ઘટના A અને એક અયુગ્મ પૂર્ણાંક પ્રાપ્ત થાય તેને ઘટના B તરીકે દર્શાવવામાં આવેલ છે. આપેલ ઘટનાઓ (i) A અથવા B (ii) A અને B (iii) A પરંતુ B નહિ (iv) 'A-નહિ' મેળવો.",
